import { callHost } from "../internal/host-error.js";
const callbacks = new Map();
let nextCallback = 1;
export const timerCallbacks = {
    async dispatch(id) {
        callbacks.get(id)?.();
    },
};
export const timersCallbacks = timerCallbacks;
/** Host task timers for engines without a JavaScript task scheduler. */
export function createTaskTimerRuntime(host) {
    return (callback, delay, kind) => {
        const key = nextCallback++;
        const repeat = kind === "interval";
        callbacks.set(key, () => {
            if (!repeat) {
                callbacks.delete(key);
            }
            callback();
        });
        let id;
        try {
            id = callHost(() => host.schedule(delay, repeat, key), (error) => Object.assign(new Error(error.message), error));
        }
        catch (error) {
            callbacks.delete(key);
            throw error;
        }
        return {
            cancel() {
                callbacks.delete(key);
                host.cancel(id);
            },
            setRef(referenced) {
                host.setRef(id, referenced);
            },
        };
    };
}
